<template><AppShell><view class="detail-crumb"><button class="text-button" @tap="backOr('people')">← IP人物索引</button><text>IP人物专题 / {{group}}</text></view><PersonPanorama v-if="group!=='JZY'" :key="group" :group="group" scene-only/><IPScenePanel v-else :key="group" :name="art.name" :art="art" :scene="scene"/><view class="ip-dossier"><view class="reading-chapters"><button @tap="section('ip-intro')">人物概览</button><button @tap="section('ip-story')">时代片段</button><button @tap="section('ip-sources')">史料依据</button><button @tap="section('ip-next')">继续循迹</button></view><StatePanel v-if="loading||error" :loading="loading" :error="error" @retry="load"/><view class="detail-layout"><view class="detail-main"><view id="ip-intro" class="section-heading compact"><view><text class="eyebrow">01 / 走近人物</text><text class="section-title">{{art.name}}的时代片段</text></view></view><text class="reading-body">{{person?.bio||overview}}</text><view v-if="group==='LYS'" class="ip-members"><text v-for="name in members" :key="name">{{name}}</text></view><view class="ip-art-note"><image :src="art.src" mode="aspectFit"/><view><text class="section-title">{{art.name}} · IP形象</text></view></view><view id="ip-story" class="section-heading compact"><view><text class="eyebrow">02 / 沿着故事</text><text class="section-title">有据可循的片段</text></view></view><template v-if="person"><view v-for="event in person.events.slice(0,4)" :key="event.id" class="chronicle-row" @tap="go('event',{id:event.id})"><view class="chronicle-date"><text>{{event.date_text}}</text></view><view><text class="row-title">{{event.title}}</text><text class="row-summary">{{event.summary}}</text><text class="small">阅读片段 ↗</text></view></view><text v-if="!person.events.length" class="muted">可从下方史料摘读继续阅读。</text></template><view v-else v-for="fact in local.facts" :key="fact.id" class="fact-card"><text class="tag">来源记载</text><text class="reading-body">{{fact.text}}</text></view><view id="ip-sources" class="section-heading compact"><view><text class="eyebrow">03 / 史料摘读</text><text class="section-title">看记载，也看依据</text></view></view><template v-if="person"><view v-for="fact in person.facts.slice(0,3)" :key="fact.id" class="fact-card"><text class="reading-body">{{fact.text}}</text><button class="text-button" @tap="sourceId=fact.source_id">查看引用与依据 ↗</button></view></template><view v-else v-for="source in local.sources" :key="source.id" class="fact-card"><text class="row-title">{{source.title}}</text><text class="muted">{{source.institution}}</text><text class="small">引用定位：{{source.position}}</text><button class="text-button" @tap="openSource(source.url)">查看原始来源 ↗</button></view><view class="aside-note"><text class="serif">史料为据，场景为引</text><text>IP外貌、场景站位和对话等艺术表达，不作为历史事实依据。江姐互动故事与史实资料分开阅读。</text></view></view><view class="detail-aside"><text class="eyebrow">继续循迹</text><view class="reading-links"><button v-if="art.personId" @tap="go('person',{id:art.personId})"><image src="/static/icons/people.png"/><view><text>人物完整档案</text><text>生平、关系与来源</text></view><text>↗</text></button><button v-if="art.personId" @tap="go('timeline',{person_id:art.personId})"><image src="/static/icons/timeline.png"/><view><text>人生长卷</text><text>按年代展开片段</text></view><text>↗</text></button><button @tap="go('learning',{group})"><image src="/static/icons/learning.png"/><view><text>人物主题挑战</text><text>入门与进阶 · 读后巩固</text></view><text>↗</text></button></view><view class="aside-note"><text class="serif">循迹读人</text><text>顶部场景可直接拖动环视，全屏后可按Esc退出。</text></view></view></view><view id="ip-next" class="next-actions"><button class="primary" @tap="go('learning',{group})">学习挑战</button><button class="outline" @tap="go('assistant',art.personId?{person_id:art.personId,name:art.name}:{})">问小迹</button><button class="outline" @tap="go('discussion',{topicId:art.personId||group})">发表评论</button><button class="text-button" @tap="backOr('people')">返回人物索引</button></view><SourceSheet :source-id="sourceId" @close="sourceId=''"/></view></AppShell></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import PersonPanorama from '../../components/PersonPanorama.vue';import IPScenePanel from '../../components/IPScenePanel.vue';import StatePanel from '../../components/StatePanel.vue';import SourceSheet from '../../components/SourceSheet.vue';import arts from '../../data/IP形象.json';import localData from '../../data/IP专项资料.json';import {api} from '../../lib/api.js';import {go,backOr} from '../../lib/navigation.js';
const group=ref('QQB'),person=ref(null),loading=ref(false),error=ref(''),sourceId=ref('');const art=computed(()=>arts[group.value]),local=computed(()=>localData[group.value]||{facts:[],sources:[]});const scenes={QQB:{path:'/panorama/qqb/场景.html',story:'qqb'},LYS:{path:'/panorama/lys/场景预览.html',story:'lys'},JZY:{path:'/vr/互动故事.html',story:'jiang'}};const scene=computed(()=>scenes[group.value]);const members=['马宝玉','葛振林','宋学义','胡德林','胡福才'];const overview=computed(()=>!['LYS','JZY'].includes(group.value)?'人物资料正在加载，可稍后重试或进入完整人物档案继续阅读。':group.value==='LYS'?'狼牙山五壮士是一组由五位战士组成的集体称谓。先在场景中了解掩护任务，再回到文字资料认识五位成员与他们各自的经历。':'江竹筠，人们熟悉的江姐。以下选取现有来源记载的求学与地下工作片段；顶部互动场景属于艺术化叙事。');let sequence=0;
async function load(){const token=++sequence;person.value=null;error.value='';loading.value=!!art.value.personId;if(!art.value.personId)return;try{const result=await api('people/'+art.value.personId);if(token===sequence)person.value=result}catch(e){if(token===sequence)error.value=e.message}finally{if(token===sequence)loading.value=false}}
function section(id){uni.pageScrollTo({selector:'#'+id,offsetTop:-120,duration:220})}function openSource(url){
// #ifdef H5
window.open(url,'_blank','noopener,noreferrer');return;
// #endif
uni.setClipboardData({data:url});}
onLoad(q=>{group.value=Object.prototype.hasOwnProperty.call(arts,q.group)?q.group:'QQB';uni.setNavigationBarTitle({title:art.value.name+' · IP人物专题'});load()});
// #ifdef H5
function syncRoute(){const [route,query='']=location.hash.slice(1).split('?');if(route!=='/pages/ip/index')return;const code=new URLSearchParams(query).get('group');const next=Object.prototype.hasOwnProperty.call(arts,code)?code:'QQB';if(group.value!==next){group.value=next;sourceId.value='';uni.setNavigationBarTitle({title:art.value.name+' · IP人物专题'});load();uni.pageScrollTo({scrollTop:0,duration:0})}}
onShow(syncRoute);onMounted(()=>window.addEventListener('hashchange',syncRoute));onBeforeUnmount(()=>{sequence++;window.removeEventListener('hashchange',syncRoute)});
// #endif
</script>
<style scoped>.ip-vr-empty{min-height:360px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:20px;background:#f1eadc;border:1px solid #dcc8a7;border-radius:9px}.ip-vr-empty button{margin:0;padding:8px 20px}.ip-art-note{display:flex;gap:24px;align-items:center;background:#f1e8d6;border-radius:12px;padding:20px;margin:28px 0}.ip-art-note image{width:110px;height:140px;flex-shrink:0}.ip-art-note view{display:flex;flex-direction:column;gap:14px}.ip-art-note .section-title{font-size:24px}.ip-members{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.ip-members text{padding:8px 14px;background:#e9ecdf;border-radius:6px;color:#354d43}@media(max-width:600px){.ip-art-note{padding:14px;gap:14px}.ip-art-note image{width:76px;height:100px}.ip-art-note .section-title{font-size:20px}}</style>
